function topoSort(graph) {
  const tasks = new Set();
  const depsMap = new Map();

  for (const task of Object.keys(graph)) {
    tasks.add(task);
    depsMap.set(task, []);
  }

  for (const task of tasks) {
    const deps = graph[task];
    if (!Array.isArray(deps)) {
      throw new Error('Invalid dependency format');
    }
    depsMap.set(task, deps.filter((dep, i, arr) => arr.indexOf(dep) === i));
    tasks.add(...deps);
  }

  if (tasks.size !== Object.keys(graph).length) {
    tasks.delete(...Object.keys(graph));
  }

  const taskArray = Array.from(tasks);
  const inDegree = new Map();
  const adj = new Map();

  for (const task of taskArray) {
    inDegree.set(task, 0);
    adj.set(task, []);
  }

  for (const task of taskArray) {
    const deps = depsMap.get(task);
    for (const dep of deps) {
      if (dep === task) {
        throw new Error('cycle');
      }
      if (!taskArray.includes(dep)) {
        throw new Error('cycle');
      }
      inDegree.set(task, inDegree.get(task) + 1);
      adj.get(dep).push(task);
    }
  }

  const result = [];
  const available = [];

  for (const task of taskArray) {
    if (inDegree.get(task) === 0) {
      available.push(task);
    }
  }

  available.sort();

  while (available.length > 0) {
    const task = available.shift();
    result.push(task);

    const neighbors = adj.get(task);
    for (const neighbor of neighbors) {
      inDegree.set(neighbor, inDegree.get(neighbor) - 1);
      if (inDegree.get(neighbor) === 0) {
        available.push(neighbor);
      }
    }
    available.sort();
  }

  if (result.length !== taskArray.length) {
    throw new Error('cycle');
  }

  return result;
}

