    const deps = graph[task];
    for (const dep of deps) {
      // dep -> task
      inDegree[task]++;
      if (!outgoing[dep]) outgoing[dep] = [];
      outgoing[dep].push(task);
    }
  }

  // Initialize queue with tasks that have no dependencies (inDegree 0)
  const queue = allTasks
    .filter(task => inDegree[task] === 0)
    .sort(); // Sort to ensure deterministic order for smallest name first

  const result = [];
  while (queue.length > 0) {
    const current = queue.shift();
    result.push(current);

    const dependents = outgoing[current] || [];
    for (const dependent of dependents) {
      inDegree[dependent]--;
      if (inDegree[dependent] === 0) {
        // Insert maintaining sorted order
