def allocate(total, weights):
    if total < 0:
        raise ValueError("total must be non-negative")
    if not weights:
        raise ValueError("weights cannot be empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights cannot be negative")
    if sum(weights) == 0:
        raise ValueError("sum of weights cannot be zero")

    s = sum(weights)
    amounts = []
    for w in weights:
        amounts.append(total * w // s)

    remainder = total - sum(amounts)
    if remainder == 0:
        return amounts

    fractional_parts = []
    for i, w in enumerate(weights):
        if w == 0:
            fractional_parts.append((0.0, i))
        else:
            frac = (total * w) % s
            fractional_parts.append((frac, i))

    # Sort by fractional part descending, then by index ascending
    fractional_parts.sort(key=lambda x: (-x[0], x[1]))

    for i in range(remainder):
        _, idx = fractional_parts[i]
        amounts[idx] += 1

    return amounts
