function topoSort(graph) {
  const allTasks = new Set();
  const dependencies = new Map();

  for (const [task, deps] of Object.entries(graph)) {
    allTasks.add(task);
    const uniqueDeps = [...new Set(deps)].filter((d) => d !== task);
    dependencies.set(task, uniqueDeps);
  }

  for (const deps of dependencies.values()) {
    for (const dep of deps) {
      allTasks.add(dep);
      if (!dependencies.has(dep)) {
        dependencies.set(dep, []);
      }
    }
  }

  const inDegree = new Map();
  for (const task of allTasks) {
    inDegree.set(task, 0);
  }

  for (const [task, deps] of dependencies.entries()) {
    for (const dep of deps) {
      inDegree.set(task, inDegree.get(task) + 1);
    }
  }

  const available = [];
  for (const task of allTasks) {
    if (inDegree.get(task) === 0) {
      available.push(task);
    }
  }

  available.sort();

  const result = [];
  while (available.length > 0) {
    const current = available.shift();
    result.push(current);

    const nextTasks = [];
    for (const [task, deps] of dependencies.entries()) {
      if (deps.includes(current)) {
        inDegree.set(task, inDegree.get(task) - 1);
        if (inDegree.get(task) === 0) {
          nextTasks.push(task);
        }
      }
    }

    nextTasks.sort();
    available.push(...nextTasks);
  }

  if (result.length !== allTasks.size) {
    throw new Error("cycle detected");
  }

  return result;
}

