function topoSort(graph) {
  const inDegree = {};
  const adj = {};
  const allNodes = new Set();

  for (const [task, deps] of Object.entries(graph)) {
    allNodes.add(task);
    inDegree[task] = 0;
    adj[task] = [];
    const uniqueDeps = [...new Set(deps)];
    for (const dep of uniqueDeps) {
      allNodes.add(dep);
      if (!(dep in inDegree)) {
        inDegree[dep] = 0;
        adj[dep] = [];
      }
      inDegree[task]++;
      adj[dep].push(task);
    }
  }

  for (const node of allNodes) {
    if (!(node in inDegree)) {
      inDegree[node] = 0;
      adj[node] = [];
    }
  }

  const result = [];
  const available = [];

  for (const node of allNodes) {
    if (inDegree[node] === 0) {
      available.push(node);
    }
  }

  available.sort();

  while (available.length > 0) {
    const current = available.shift();
    result.push(current);

    for (const neighbor of adj[current]) {
      inDegree[neighbor]--;
      if (inDegree[neighbor] === 0) {
        available.push(neighbor);
      }
    }
    available.sort();
  }

  if (result.length !== allNodes.size) {
    throw new Error('cycle detected');
  }

  return result;
}

