    end_date = _parse_date(end)

    if start_date >= end_date:
        return 0

    holidays_set = {date.fromisoformat(h) for h in holidays}

    count = 0
    current = start_date
    while current < end_date:
        if current.weekday() < 5 and current not in holidays_set:
            count += 1
        current += timedelta(days=1)

    return count
