def allocate(total, weights):
    if total < 0:
        raise ValueError("total must be non-negative")
    if not weights:
        raise ValueError("weights must not be empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights must not contain negative values")
    if sum(weights) == 0:
        raise ValueError("weights must not sum to zero")

    total_weight = sum(weights)
    allocated = [0] * len(weights)
    remainders = []

    for i, w in enumerate(weights):
        share = (total * w) // total_weight
        allocated[i] = share
        remainders.append((total * w) % total_weight)

    remainder_count = total - sum(allocated)
    if remainder_count > 0:
        # Sort by remainder descending, then by index ascending
        indices = sorted(range(len(weights)), key=lambda i: (-remainders[i], i))
        for i in range(remainder_count):
            recipient = indices[i]
            allocated[recipient] += 1

    return allocated
