  const tasks = new Set();
  const adj = {};
  const inDegree = {};

  for (const [task, deps] of Object.entries(graph)) {
    tasks.add(task);
    if (!adj[task]) adj[task] = new Set();
    for (const dep of deps) {
      tasks.add(dep);
      if (!adj[dep]) adj[dep] = new Set();
      if (!adj[task].has(dep)) {
        adj[task].add(dep);
        inDegree[task] = (inDegree[task] || 0) + 1;
      }
    }
  }

  for (const task of tasks) {
    if (inDegree[task] === undefined) inDegree[task] = 0;
  }

  const sorted = [];
  const available = [];

  for (const task of tasks) {
    if (inDegree[task] === 0) {
      available.push(task);
    }
  }

  available.sort();

  while (available.length > 0) {
    const current = available.shift();
    sorted.push(current);

    const nextTasks = [];
    for (const task of tasks) {
      if (adj[task].has(current)) {
        inDegree[task]--;
        if (inDegree[task] === 0) nextTasks.push(task);
      }
    }
    nextTasks.sort();
    for (const task of nextTasks) {
      const idx = available.indexOf(task);
      if (idx >= 0) {
        available.splice(idx, 1);
      } else {
        available.push(task);
      }
    }
    available.sort();
  }

  if (sorted.length !== tasks.size) {
    throw new Error("cycle detected");
  }

  return sorted;
}

