                return
            for key, value in current_obj.items():
                new_path = f"{path}{sep}{key}" if path else str(key)
                _flatten(value, new_path)
        elif isinstance(current_obj, list):
            if not current_obj:
                # Empty list is a leaf
                result[path] = current_obj
                return
            for idx, value in enumerate(current_obj):
                new_path = f"{path}{sep}{idx}"
                _flatten(value, new_path)
        else:
            # Leaf value (including tuples, sets, None, primitives)
            result[path] = current_obj

    _flatten(obj, "")
    return result
