def allocate(total, weights):
    if total < 0:
        raise ValueError("total must be non-negative")
    if not weights:
        raise ValueError("weights must not be empty")
    if all(w < 0 for w in weights):
        raise ValueError("weights must not be all negative")
    if all(w == 0 for w in weights):
        raise ValueError("weights cannot be all zero")

    if any(w < 0 for w in weights):
        raise ValueError("weights must be non-negative")

    weight_sum = sum(weights)
    base_amounts = [(w // weight_sum) * total for w in weights]
    # Actually, base share per recipient is floor(total * w / weight_sum)
    base_amounts = [total * w // weight_sum for w in weights]

    remaining = total - sum(base_amounts)
    remainders = []
    for i, w in enumerate(weights):
        rem = (total * w) % weight_sum
        remainders.append((rem, i))

    remainders.sort(reverse=True)

    result = list(base_amounts)
    for i in range(remaining):
        _, idx = remainders[i]
        result[idx] += 1

    return result

