  const pairs = qs.slice(index).split('&');

  for (let i = 0; i < pairs.length; i++) {
    const pair = pairs[i];

    // Skip empty pairs
    if (pair.length === 0) continue;

    // Split at first =
    let eqIndex = pair.indexOf('=');
    let key, value;

    if (eqIndex === -1) {
      key = pair;
      value = '';
    } else {
      key = pair.slice(0, eqIndex);
      value = pair.slice(eqIndex + 1);
    }

    // Decode key: + -> space, then percent decode
    let decodedKey = decodeURIComponent(key.replace(/\+/g, ' '));

    // Skip if decoded key is empty
    if (decodedKey.length === 0) continue;

    // Decode value: + -> space, then percent decode
    let decodedValue;
    try {
      // First replace + with space for value as well
      let rawValue = value.replace(/\+/g, ' ');
      decodedValue = decodeURIComponent(rawValue);
    } catch (e) {
      if (e instanceof URIError) {
        throw e;
      }
      throw new URIError('Invalid percent encoding in value');
    }

    // Handle single vs multiple values
    if (Object.prototype.hasOwnProperty.call(result, decodedKey)) {
      if (!Array.isArray(result[decodedKey])) {
        result[decodedKey] = [result[decodedKey]];
      }
      result[decodedKey].push(decodedValue);
    } else {
      result[decodedKey] = decodedValue;
    }
  }

  return result;
}

