function isValidCardNumber(input) {
  if (typeof input !== 'string') {
    return false;
  }

  let cleaned = '';
  for (let i = 0; i < input.length; i++) {
    const char = input[i];
    if (char === ' ' || char === '-') {
      continue;
    }
    if (!/^\d$/.test(char)) {
      return false;
    }
    cleaned += char;
  }

  if (cleaned.length < 12 || cleaned.length > 19) {
    return false;
  }

  let sum = 0;
  let isSecond = false;
  for (let i = cleaned.length - 1; i >= 0; i--) {
    let digit = parseInt(cleaned[i], 10);
    if (isSecond) {
      digit *= 2;
      if (digit > 9) {
        digit -= 9;
      }
    }
    sum += digit;
    isSecond = !isSecond;
  }

  return sum % 10 === 0;
}

