class LRUCache:
    class _Node:
        __slots__ = ('key', 'value', 'prev', 'next')
        def __init__(self, key, value):
            self.key = key
            self.value = value
            self.prev = None
            self.next = None

    def __init__(self, capacity):
        if not isinstance(capacity, int):
            raise TypeError("capacity must be an int")
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self.capacity = capacity
        self.head = None  # Least recently used
        self.tail = None  # Most recently used
        self._map = {}
        self._size = 0

    def _add_to_head(self, node):
        """Prepend node at the tail end (most recently used)."""
        node.next = self.tail
        node.prev = self.tail.prev if self.tail else None
        if self.tail:
            self.tail.prev = node
        else:
            self.head = node
        self.tail = node

    def _remove_node(self, node):
        """Remove node from the doubly linked list."""
        if node.prev:
            node.prev.next = node.next
        else:
            self.head = node.next

        if node.next:
            node.next.prev = node.prev
        else:
            self.tail = node.prev

        node.prev = node.next = None

    def _move_to_head(self, node):
        """Move existing node to the tail end (most recently used)."""
        self._remove_node(node)
        self._add_to_head(node)

    def get(self, key, default=None):
        if key in self._map:
            self._move_to_head(self._map[key])
            return self._map[key].value
        return default

    def put(self, key, value):
        if key in self._map:
            self._map[key].value = value
            self._move_to_head(self._map[key])
            return

        new_node = self._Node(key, value)
        self._map[key] = new_node
        self._add_to_head(new_node)
        self._size += 1

        if self._size > self.capacity:
            lru_node = self.head
            self._remove_node(lru_node)
            del self._map[lru_node.key]
            self._size -= 1

    def __len__(self):
        return self._size

    def __contains__(self, key):
        return key in self._map

    def keys(self):
        """Return keys ordered from least recently used to most recently used."""
        result = []
        current = self.head
        while current:
            result.append(current.key)
            current = current.prev
        return result
