def allocate(total, weights):
    if total < 0:
        raise ValueError("total must be non-negative")
    if not weights:
        raise ValueError("weights must not be empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights must be non-negative")
    if sum(weights) == 0:
        raise ValueError("weights must not be all zero")

    total_weight = sum(weights)
    amounts = []
    remainders = []

    for w in weights:
        share = (total * w) // total_weight
        remainder = (total * w) % total_weight
        amounts.append(share)
        remainders.append(remainder)

    remainder_count = total - sum(amounts)
    if remainder_count > 0:
        paired = list(zip(range(len(weights)), remainders))
        paired.sort(key=lambda x: (-x[1], x[0]))

        for i in range(remainder_count):
            amounts[paired[i][0]] += 1

    return amounts
