  const pairs = qs.split('&');

  for (let i = 0; i < pairs.length; i++) {
    const pair = pairs[i];

    // Skip empty pairs (e.g., trailing '&', or '&&')
    if (pair === '') {
      continue;
    }

    const eqIndex = pair.indexOf('=');
    let key, value;

    if (eqIndex === -1) {
      // No '=' found: key is the whole string, value is ''
      key = pair;
      value = '';
    } else {
      key = pair.slice(0, eqIndex);
      value = pair.slice(eqIndex + 1);
    }

    // Skip if decoded key is empty
    const decodedKey = decodeURIComponent(key.replace(/\+/g, ' '));
    if (decodedKey === '') {
      continue;
    }

    // Decode key and value
    let decodedValue;
    try {
      decodedKey = decodeURIComponent(key.replace(/\+/g, ' '));
      decodedValue = decodeURIComponent(value.replace(/\+/g, ' '));
    } catch (e) {
      if (e instanceof URIError) {
        throw new URIError('Malformed percent-encoding');
      }
      throw e;
    }

    // Accumulate into result
    if (decodedKey in result) {
      if (!Array.isArray(result[decodedKey])) {
        result[decodedKey] = [result[decodedKey]];
      }
      result[decodedKey].push(decodedValue);
    } else {
      result[decodedKey] = decodedValue;
    }
  }

