  for (const task in graph) {
    const deps = graph[task];
    if (!Array.isArray(deps)) {
      throw new Error('Invalid graph format');
    }
    // Deduplicate and sort for consistent processing
    const uniqueDeps = [...new Set(deps)].sort();
    for (const dep of uniqueDeps) {
      taskSet.add(dep);
      if (!adj[dep]) adj[dep] = [];
      if (!inDegree[dep]) inDegree[dep] = 0;
      adj[dep].push(task);
      inDegree[task]++;
    }
  }

  // Ensure all tasks are in inDegree
  for (const task of taskSet) {
    if (!(task in inDegree)) inDegree[task] = 0;
  }

  // Topological sort with cycle detection
  const result = [];
  const available = [];

  // Initialize with tasks having no dependencies
  for (const task of taskSet) {
    if (inDegree[task] === 0) {
      available.push(task);
    }
