function parseQuery(qs) {
  if (typeof qs !== 'string') {
    throw new TypeError('Expected a string');
  }

  // Remove leading '?' if present
  let str = qs;
  if (str.startsWith('?')) {
    str = str.slice(1);
  }

  if (str === '') {
    return {};
  }

  const result = {};
  const pairs = str.split('&');

  for (const pair of pairs) {
    // Skip empty pairs (e.g., trailing & or &&)
    if (pair === '') {
      continue;
    }

    // Split at first '='
    const eqIndex = pair.indexOf('=');
    let key, value;

    if (eqIndex === -1) {
      key = pair;
      value = '';
    } else {
      key = pair.slice(0, eqIndex);
      value = pair.slice(eqIndex + 1);
    }

    // Decode key and value
    const decodedKey = decodeURIComponent(key);
    const decodedValue = decodeURIComponent(value);

    // Skip if key is empty after decoding
    if (decodedKey === '') {
      continue;
    }

    // Determine if key appears multiple times
    if (decodedKey in result) {
      if (!Array.isArray(result[decodedKey])) {
        result[decodedKey] = [result[decodedKey]];
      }
      result[decodedKey].push(decodedValue);
    } else {
      result[decodedKey] = decodedValue;
    }
  }

  return result;
}

module.exports = { parseQuery };

