function topoSort(graph) {
  const tasks = new Set();
  const adj = new Map();

  for (const [task, deps] of Object.entries(graph)) {
    tasks.add(task);
    const uniqueDeps = [...new Set(deps)].filter((d) => d !== task);
    if (!adj.has(task)) {
      adj.set(task, []);
    }
    for (const dep of uniqueDeps) {
      tasks.add(dep);
      if (!adj.has(dep)) {
        adj.set(dep, []);
      }
      adj.get(task).push(dep);
    }
  }

  for (const task of tasks) {
    if (!adj.has(task)) {
      adj.set(task, []);
    }
  }

  const inDegree = new Map();
  for (const task of tasks) {
    inDegree.set(task, 0);
  }
  for (const [task, deps] of adj.entries()) {
    for (const dep of deps) {
      inDegree.set(task, inDegree.get(task) + 1);
    }
  }

  const result = [];
  const available = [];
  for (const task of tasks) {
    if (inDegree.get(task) === 0) {
      available.push(task);
    }
  }
  available.sort();

  while (available.length > 0) {
    const current = available.shift();
    result.push(current);
    const outgoing = adj.get(current);
    for (const target of outgoing) {
      inDegree.set(target, inDegree.get(target) - 1);
      if (inDegree.get(target) === 0) {
        available.push(target);
      }
    }
    available.sort();
  }

  if (result.length !== tasks.size) {
    throw new Error('cycle detected');
  }

  return result;
}

