function topoSort(graph) {
  const allTasks = new Set();
  const adjacency = {};

  // Collect all tasks and build a reverse dependency map (task -> list of tasks that depend on it)
  // Also record the set of direct dependencies for each task
  for (const [task, deps] of Object.entries(graph)) {
    allTasks.add(task);
    const uniqueDeps = [...new Set(deps)].filter((dep) => dep !== task); // Remove self-loops for cycle detection later
    adjacency[task] = uniqueDeps;
    allTasks.add(task);
  }

  // Add tasks that appear only in dependency lists
  for (const deps of Object.values(graph)) {
    for (const dep of deps) {
      allTasks.add(dep);
      if (!adjacency.has(dep)) {
        adjacency[dep] = [];
      }
    }
  }

  // Initialize in-degree for each task (number of unmet dependencies)
  const inDegree = new Map();
  for (const task of allTasks) {
    const deps = adjacency[task] || [];
    inDegree.set(task, deps.length);
  }

  // Queue of tasks with in-degree 0, sorted by name to ensure deterministic selection
  const queue = Array.from(inDegree.entries())
    .filter(([_, degree]) => degree === 0)
    .map(([task]) => task)
    .sort();

  const result = [];
  while (queue.length > 0) {
    const current = queue.shift();
    result.push(current);

    // Decrease in-degree for all tasks that depend on current
    for (const [dependent, deps] of Object.entries(adjacency)) {
      if (deps.includes(current)) {
        inDegree.set(dependent, inDegree.get(dependent) - 1);
        if (inDegree.get(dependent) === 0) {
          queue.push(dependent);
        }
      }
    }
    // Re-sort the queue to maintain lexicographical order for deterministic selection
    queue.sort();
  }

  // If we didn't process all tasks, there is a cycle
  if (result.length !== allTasks.size) {
    throw new Error('cycle detected');
  }

  return result;
}

