class LRUCache:
    class _Node:
        __slots__ = ('key', 'value', 'prev', 'next')

        def __init__(self, key, value):
            self.key = key
            self.value = value
            self.prev = None
            self.next = None

    def __init__(self, capacity):
        if not isinstance(capacity, int):
            raise TypeError("capacity must be an int")
        if capacity < 1:
            raise ValueError("capacity must be at least 1")

        self.capacity = capacity
        self.size = 0
        self.head = None  # Least recently used
        self.tail = None  # Most recently used
        self._store = {}  # key -> _Node

    def _move_to_tail(self, node):
        """Move a node to the tail (most recently used position)."""
        if node is self.tail:
            return

        # Remove from current position
        if node.prev:
            node.prev.next = node.next
        else:
            # This is the head
            self.head = node.next

        if node.next:
            node.next.prev = node.prev

        # Insert at tail
        node.next = None
        node.prev = self.tail
        if self.tail:
            self.tail.next = node
        self.tail = node

        if self.head is None:
            self.head = node

    def get(self, key, default=None):
        if key not in self._store:
            return default

        node = self._store[key]
        self._move_to_tail(node)
        return node.value

    def put(self, key, value):
        node = self._store.get(key)

        if node is not None:
            node.value = value
            self._move_to_tail(node)
            return

        # Create new node
        new_node = self._Node(key, value)
        self._store[key] = new_node
        self._move_to_tail(new_node)
        self.size += 1

        # Evict if over capacity
        if self.size > self.capacity:
            lru_node = self.head
            del self._store[lru_node.key]
            self.size -= 1
            # Remove from list
            if lru_node.prev:
                lru_node.prev.next = lru_node.next
            else:
                self.head = lru_node.next
            if lru_node.next:
                lru_node.next.prev = lru_node.prev

    def __len__(self):
        return self.size

    def __contains__(self, key):
        return key in self._store

    def keys(self):
        """Returns a list of keys ordered from least recently used to most recently used."""
        result = []
        current = self.head
        while current:
            result.append(current.key)
            current = current.next
        return result
