def allocate(total, weights):
    if total < 0:
        raise ValueError("total must be non-negative")
    if not weights:
        raise ValueError("weights must not be empty")
    if any(w < 0 for w in weights):
        raise ValueError("weights must be non-negative")
    if sum(weights) == 0:
        raise ValueError("weights cannot be all zero")

    total_weight = sum(weights)
    base_amounts = [int(total * w / total_weight) for w in weights]
    remainders = [total * w / total_weight - base_amounts[i] for i, w in enumerate(weights)]

    leftover = total - sum(base_amounts)
    if leftover == 0:
        return base_amounts

    indexed_remainders = [(i, remainders[i]) for i in range(len(weights))]
    indexed_remainders.sort(key=lambda x: (-x[1], x[0]))

    result = list(base_amounts)
    for i in range(leftover):
        idx = indexed_remainders[i][0]
        result[idx] += 1

    return result

