function deepEqual(a, b) {
  if (a === b) {
    // Handle NaN specifically since NaN !== NaN
    if (Number.isNaN(a)) return true;
    // Handle -0 and +0: they are equal by ===, but let's ensure we treat them as equal
    // (0 === -0 is true in JS, so this is fine)
    return true;
  }

  if (a === null && b === null) return true;
  if (a === null || b === null) return false;

  if (typeof a !== 'object' || typeof b !== 'object') {
    return false;
  }

  // Handle Date objects
  if (a instanceof Date && b instanceof Date) {
    return a.getTime() === b.getTime();
  }

  // Handle Functions
  if (typeof a === 'function' && typeof b === 'function') {
    return a === b;
  }

  // Handle Arrays
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i])) return false;
    }
    return true;
  }

  // Handle Plain Objects
  const keysA = Object.keys(a);
  const keysB = Object.keys(b);

  if (keysA.length !== keysB.length) return false;

  for (const key of keysA) {
    // Check if key exists in b and values are deeply equal
    if (!(key in b) || !deepEqual(a[key], b[key])) {
      return false;
    }
  }

  // Ensure b doesn't have extra keys (handled by length check, but let's be explicit for own enumerable)
  for (const key of keysB) {
    if (!(key in a)) {
      return false;
    }
  }

  return true;
}

