def parse_csv_line(line):
    if not isinstance(line, str):
        raise TypeError("line must be a str")

    fields = []
    i = 0
    n = len(line)

    while i < n:
        if line[i] == ',':
            fields.append('')
            i += 1
            continue

        if line[i] == '"':
            # Quoted field
            start = i
            i += 1
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Escaped quote
                        i += 2
                        continue
                    else:
                        # Closing quote
                        i += 1
                        break
                else:
                    i += 1
            else:
                raise ValueError("unterminated quoted field")

            if i < n and line[i] != ',':
                raise ValueError("unexpected character after closing quote")

            # Extract the substring from start+1 to i-1, processing escapes
            field_chars = []
            j = start + 1
            while j < i:
                if line[j] == '"':
                    if j + 1 < i and line[j + 1] == '"':
                        field_chars.append('"')
                        j += 2
                        continue
                    else:
                        field_chars.append('"')
                        j += 1
                        continue
                field_chars.append(line[j])
                j += 1
            fields.append(''.join(field_chars))
        else:
            # Unquoted field
            start = i
            while i < n and line[i] != ',':
                i += 1
            fields.append(line[start:i])

    return fields
