def rle_encode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    for char in s:
        if char in '0123456789':
            raise ValueError("Input must not contain digit characters")
    if not s:
        return ""

    result = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            result.append(str(count) + s[i - 1])
            count = 1
    result.append(str(count) + s[-1])
    return "".join(result)


def rle_decode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    if not s:
        return ""

    result = []
    i = 0
    while i < len(s):
        # Parse count
        if s[i].isdigit():
            count_str = ""
            while i < len(s) and s[i].isdigit():
                count_str += s[i]
                i += 1
            if not count_str:
                raise ValueError("Missing count")
            count = int(count_str)
            if count == 0:
                raise ValueError("Count cannot be zero")
        else:
            raise ValueError("Missing count")

        # Parse character
        if i >= len(s):
            raise ValueError("Trailing digits with no character")
        char = s[i]
        if char.isdigit():
            raise ValueError("Character must be non-digit")
        i += 1

        result.append(char * count)

    return "".join(result)
