    const [current, remainingDepth] = stack.pop();

    if (remainingDepth === 0) {
      result.push(current);
      continue;
    }

    for (let i = current.length - 1; i >= 0; i--) {
      const item = current[i];
      if (Array.isArray(item)) {
        stack.push([item, remainingDepth - 1]);
      } else {
        result.push(item);
      }
    }
  }

