function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',').map(p => p.trim());
  const result = [];

  for (const part of parts) {
    if (part === '') {
      throw new SyntaxError('empty part or leading/trailing comma');
    }

    if (part.includes('+') || part.includes('.') || /[a-zA-Z]/.test(part)) {
      throw new SyntaxError(`malformed part: ${part}`);
    }

    const dashIndex = part.indexOf('-');
    if (dashIndex === -1) {
      const num = parseInt(part, 10);
      if (isNaN(num)) {
        throw new SyntaxError(`malformed part: ${part}`);
      }
      if (num < 0) {
        throw new SyntaxError(`negative number in part: ${part}`);
      }
      result.push(num);
      continue;
    }

    if (dashIndex !== part.length - 1) {
      throw new SyntaxError('missing end in range: ' + part);
    }

    const loStr = part.slice(0, dashIndex);
    const hiStr = part.slice(dashIndex + 1);

    if (loStr === '' || hiStr === '') {
      throw new SyntaxError('empty part or leading/trailing comma');
    }

    const lo = parseInt(loStr, 10);
    const hi = parseInt(hiStr, 10);

    if (isNaN(lo) || isNaN(hi)) {
      throw new SyntaxError(`malformed part: ${part}`);
    }

    if (lo < 0 || hi < 0) {
      throw new SyntaxError(`negative number in part: ${part}`);
    }

    if (lo > hi) {
      throw new RangeError(`range start greater than end: ${lo}-${hi}`);
    }

    if (loStr.includes('-') || hiStr.includes('-')) {
      throw new SyntaxError('more than one dash in range: ' + part);
    }

    for (let i = lo; i <= hi; i++) {
      result.push(i);
    }
  }

  const seen = new Set();
  const unique = [];
  for (const num of result) {
    if (!seen.has(num)) {
      seen.add(num);
      unique.push(num);
    }
  }

  return unique;
}

