function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',').filter(p => p.trim() !== '');
  const result = [];

  for (const part of parts) {
    const trimmed = part.trim();

    if (trimmed === '') {
      throw new SyntaxError('Empty part');
    }

    if (/^[0-9-]+$/.test(trimmed) && !trimmed.includes('-')) {
      // Single number
      let num = parseInt(trimmed, 10);
      if (isNaN(num)) {
        throw new SyntaxError('Invalid number format');
      }
      result.push(num);
      continue;
    }

    // Check for multiple dashes or invalid characters
    const dashCount = (trimmed.match(/-/g) || []).length;
    if (dashCount !== 1) {
      throw new SyntaxError('Invalid range format: ' + trimmed);
    }

    const [loStr, hiStr] = trimmed.split('-');

    if (!/^[0-9]+$/.test(loStr)) {
      throw new SyntaxError('Invalid start number: ' + loStr);
    }
    if (!/^[0-9]+$/.test(hiStr)) {
      throw new SyntaxError('Invalid end number: ' + hiStr);
    }

    const lo = parseInt(loStr, 10);
    const hi = parseInt(hiStr, 10);

    if (lo > hi) {
      throw new RangeError('Range start ' + lo + ' is greater than end ' + hi);
    }

    for (let i = lo; i <= hi; i++) {
      result.push(i);
    }
  }

  return Array.from(new Set(result).sort((a, b) => a - b));
}

module.exports = { expandRanges };
