def parse_csv_line(line):
    if not isinstance(line, str):
        raise TypeError("line must be a string")

    fields = []
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            # Start of quoted field
            value = []
            i += 1
            while i < n:
                ch = line[i]
                if ch == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Escaped quote: add one quote and skip next
                        value.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        break
                else:
                    value.append(ch)
                    i += 1
            else:
                raise ValueError("unclosed quoted field")

            # After closing quote, must be comma or end of line
            if i < n and line[i] != ',':
                raise ValueError("expected comma or end of line after quoted field")

            fields.append(''.join(value))
        else:
            # Unquoted field
            start = i
            while i < n and line[i] != ',':
                i += 1
            fields.append(line[start:i])
            # If there are more characters, the next one must be a comma
            if i < n and line[i] != ',':
                raise ValueError("unexpected character after unquoted field")
            i += 1  # Skip the comma

    return fields
