    this._events = Object.create(null);
  }

  _register(event, fn, isOnce) {
    if (typeof fn !== 'function') {
      throw new TypeError('fn must be a function');
    }
    const listeners = this._events[event];
    if (!listeners) {
      this._events[event] = [
        { fn, isOnce, id: ++this._listenerId },
      ];
    } else {
      listeners.push({ fn, isOnce, id: ++this._listenerId });
    }
    return this;
  }

  on(event, fn) {
    this._register(event, fn, false);
    return this;
  }

  once(event, fn) {
    this._register(event, fn, true);
    return this;
  }

  off(event, fn) {
    const listeners = this._events[event];
    if (!listeners) {
      return this;
    }
    const newListeners = [];
    for (const listener of listeners) {
      if (listener.fn !== fn) {
        newListeners.push(listener);
      }
    }
    this._events[event] = newListeners.length > 0 ? newListeners : null;
    return this;
  }

  emit(event, ...args) {
    const listeners = this._events[event];
    if (!listeners) {
      return false;
    }
    const originalListeners = listeners.map((l) => ({ ...l }));
    let calledAtLeastOne = false;
    for (const listener of originalListeners) {
      if (listener.isOnce) {
        this.off(event, listener.fn);
      }
      listener.fn.apply(this, args);
      calledAtLeastOne = true;
    }
    return calledAtLeastOne;
  }

  listenerCount(event) {
    const listeners = this._events[event];
    return listeners ? listeners.length : 0;
  }
}

