function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',').filter(p => p.trim() !== '');
  const result = new Set();

  for (const part of parts) {
    if (part.length === 0) {
      throw new SyntaxError('Empty part');
    }

    const dashIndex = part.indexOf('-');
    let lo, hi;

    if (dashIndex === -1) {
      // Single number
      const num = parseInt(part, 10);
      if (isNaN(num) || part.length > 1 && part[0] === '0' || part < '0' || part > '9'.repeat(part.length)) {
        // Check for invalid characters, decimals, plus, etc.
        if (!/^\d+$/.test(part)) {
          throw new SyntaxError('Malformed number part');
        }
        // Leading zero check for non-zero numbers is handled by parseInt + validation, 
        // but we need to ensure it parses correctly as a non-negative integer.
        // The regex /^\d+$/ allows leading zeros. The parseInt handles them.
        // We just need to ensure it's not negative (parseInt of negative string is negative)
        // and not NaN.
        if (isNaN(num)) {
          throw new SyntaxError('Malformed number part');
        }
        if (num < 0) {
          throw new SyntaxError('Negative number');
        }
        result.add(num);
      } else {
        // Valid digit string
        const num = parseInt(part, 10);
        result.add(num);
      }
    } else if (dashIndex === 0 || dashIndex === part.length - 1) {
      // Malformed: range starting or ending with dash
      throw new SyntaxError('Malformed range part');
    } else {
      const loStr = part.substring(0, dashIndex);
      const hiStr = part.substring(dashIndex + 1);

      if (!/^\d+$/.test(loStr) || !/^\d+$/.test(hiStr)) {
        throw new SyntaxError('Malformed range part');
      }

      lo = parseInt(loStr, 10);
      hi = parseInt(hiStr, 10);

      if (isNaN(lo) || isNaN(hi)) {
        throw new SyntaxError('Malformed range part');
      }

      if (lo < 0 || hi < 0) {
        throw new SyntaxError('Negative number in range');
      }

      if (lo > hi) {
        throw new RangeError('Range start must not exceed range end');
      }

      for (let i = lo; i <= hi; i++) {
        result.add(i);
      }
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

