    const targetDepth = Number.isFinite(depth) ? Math.floor(depth) : Infinity;

    for (const item of arr) {
        if (targetDepth === 0) {
            result.push(item);
        } else if (Array.isArray(item)) {
            if (item.length === 0) {
                continue;
            }
            const flattenedItem = flatten(item, targetDepth - 1);
            result.push(...flattenedItem);
        } else {
            result.push(item);
        }
    }

