      return [];
    }
    return this._events[event];
  }

  on(event, fn) {
    this._validateFn(fn);
    const listeners = this._getListeners(event);
    listeners.push(fn);
    return this;
  }

  once(event, fn) {
    this._validateFn(fn);
    const listeners = this._getListeners(event);
    listeners.push(function (...args) {
      this.off(event, fn);
      return fn.apply(this, args);
    }.bind(this));
    return this;
  }

  off(event, fn) {
    if (event === undefined || event === null) {
      return this;
    }
    const listeners = this._getListeners(event);
    if (listeners.length === 0) {
      return this;
    }
    const index = listeners.indexOf(fn);
    if (index !== -1) {
      listeners.splice(index, 1);
    }
    return this;
