      }
      if (part.includes('+') || part.includes('.') || part.startsWith('-')) {
        throw new SyntaxError('invalid format: ' + part);
      }
      if (part.length > 1 && part[0] === '0' && part !== '0') {
        throw new SyntaxError('leading zero: ' + part);
      }
      result.push(num);
    } else if (dashIndex === 0 || dashIndex === part.length - 1) {
      throw new SyntaxError('missing end or start: ' + part);
    } else {
      const startStr = part.substring(0, dashIndex);
      const endStr = part.substring(dashIndex + 1);

      const start = Number(startStr);
      const end = Number(endStr);

      if (Number.isNaN(start) || Number.isNaN(end)) {
        throw new SyntaxError('invalid number in range: ' + part);
      }
      if (startStr.includes('+') || startStr.includes('.') || startStr.startsWith('-')) {
        throw new SyntaxError('invalid format in range: ' + part);
      }
      if (endStr.includes('+') || endStr.includes('.') || endStr.startsWith('-')) {
        throw new SyntaxError('invalid format in range: ' + part);
      }
      if (startStr.length > 1 && startStr[0] === '0') {
        throw new SyntaxError('leading zero in range start: ' + part);
      }
      if (endStr.length > 1 && endStr[0] === '0') {
        throw new SyntaxError('leading zero in range end: ' + part);
      }
      if (start > end) {
        throw new RangeError('start > end in range: ' + part);
      }
      if (start < 0) {
        throw new SyntaxError('negative number: ' + part);
      }
      for (let i = start; i <= end; i++) {
        result.push(i);
      }
    }
  }

  return [...new Set(result).sort((a, b) => a - b)];
}

