def parse_csv_line(line):
    if not isinstance(line, str):
        raise TypeError("line must be a string")

    fields = []
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            # Start of a quoted field
            start = i
            i += 1
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Escaped quote
                        fields.append(line[start:i+1].replace('""', '"'))
                        i += 2
                    else:
                        # End of quoted field
                        fields.append(line[start:i])
                        i += 1
                        break
                else:
                    i += 1
            else:
                # Reached end of string without closing quote
                raise ValueError("unclosed quoted field")
        elif line[i] == ',':
            fields.append('')
            i += 1
        else:
            # Start of an unquoted field
            start = i
            while i < n and line[i] != ',':
                i += 1
            fields.append(line[start:i])
            if i < n:
                i += 1
            else:
                # End of line reached while processing an unquoted field
                pass
    return fields
