    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    if any(c.isdigit() for c in s):
        raise ValueError("Input must not contain digit characters")
    if not s:
        return ""
    result = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            result.append(f"{count}{s[i - 1]}")
            count = 1
    result.append(f"{count}{s[-1]}")
    return "".join(result)

def rle_decode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    if not s:
        return ""
    result = []
    i = 0
    while i < len(s):
        if not s[i].isdigit():
            raise ValueError("Missing count")
        count_str = ""
        while i < len(s) and s[i].isdigit():
            count_str += s[i]
            i += 1
        if not s[i].isalpha():  # Character must be non-digit
            raise ValueError("Trailing digits with no character" if count_str else "Missing count")
        count = int(count_str)
        if count == 0:
            raise ValueError("Count must be at least 1")
        char = s[i]
        result.append(char * count)
        i += 1
    return "".join(result)
