function formatBytes(n) {
  if (typeof n !== 'number' || !Number.isFinite(n)) {
    throw new TypeError('n must be a finite number');
  }
  if (!Number.isInteger(n) || n < 0) {
    throw new RangeError('n must be a non-negative integer');
  }

  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let value = n;
  let unitIndex = 0;

  while (value >= 1024 && unitIndex < units.length - 1) {
    value /= 1024;
    unitIndex++;
  }

  // If rounding up would push us to the next unit and a larger unit exists, promote
  if (Math.round(value * 10) >= 1024 && unitIndex < units.length - 1) {
    value = Math.round(value);
    if (value >= 1024) {
      value /= 1024;
      unitIndex++;
    }
  }

  let strValue = value.toFixed(1);
  if (strValue === '0.0') {
    strValue = '0';
  } else if (strValue.endsWith('.0')) {
    strValue = strValue.slice(0, -2);
  }

  return strValue + ' ' + units[unitIndex];
}

module.exports = { formatBytes };
