        let called = false;
        if (listeners) {
            called = listeners.some(fn => {
                fn.apply(this, args);
                return true;
            });
        }
        return called;
    }

    listenerCount(event) {
        const listeners = this._events.get(event);
        return listeners ? listeners.length : 0;
    }
