def rle_encode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    if any(c.isdigit() for c in s):
        raise ValueError("Input must not contain any digit character")
    if not s:
        return ""
    result = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            result.append(str(count) + s[i - 1])
            count = 1
    result.append(str(count) + s[-1])
    return "".join(result)

def rle_decode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    if not s:
        return ""
    result = []
    i = 0
    while i < len(s):
        if s[i].isdigit():
            start = i
            while i < len(s) and s[i].isdigit():
                i += 1
            count_str = s[start:i]
            if count_str == "0":
                raise ValueError("Count must be at least 1")
            count = int(count_str)
            if i >= len(s):
                raise ValueError("Trailing digits with no character")
            char = s[i]
            if char.isdigit():
                raise ValueError("Character must not be a digit")
            result.append(char * count)
            i += 1
        else:
            raise ValueError("Missing count before character")
    return "".join(result)
