function formatBytes(n) {
  if (typeof n !== 'number' || !Number.isFinite(n) || !Number.isInteger(n)) {
    throw new TypeError('n must be a finite integer number');
  }
  if (n < 0) {
    throw new RangeError('n must be non-negative');
  }

  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let unitIndex = 0;
  let value = n;

  while (value >= 1024 && unitIndex < units.length - 1) {
    value /= 1024;
    unitIndex++;
  }

  let formattedValue = Math.round(value * 10) / 10;
  let unit = units[unitIndex];

  // If rounding pushed the value to 1024 and there is a larger unit, move up
  if (formattedValue === 1024 && unitIndex < units.length - 1) {
    formattedValue = 1;
    unitIndex++;
    unit = units[unitIndex];
  }

  if (formattedValue % 1 === 0) {
    return `${formattedValue} ${unit}`;
  } else {
    return `${formattedValue.toFixed(1)} ${unit}`;
  }
}

