    if (!this._events[event]) {
      return this;
    }
    const listeners = this._events[event];
    const index = listeners.indexOf(fn);
    if (index === -1) {
      return this;
    }
    listeners.splice(index, 1);
    return this;
  }

  emit(event, ...args) {
    const listeners = this._events[event] || [];
    let anyCalled = false;
    for (const fn of listeners) {
      fn.apply(this, args);
      anyCalled = true;
    }
    return anyCalled;
  }

  listenerCount(event) {
    return (this._events[event] || []).length;
  }
}

