def parse_csv_line(line):
    if not isinstance(line, str):
        raise TypeError("line must be a string")

    fields = []
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            # Quoted field
            start = i + 1
            i += 1
            field_chars = []

            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Escaped quote
                        field_chars.append('"')
                        i += 2
                    else:
                        # Closing quote
                        i += 1
                        break
                else:
                    field_chars.append(line[i])
                    i += 1
            else:
                # Loop completed without break -> unclosed quote
                raise ValueError("unclosed quoted field")

            # Check what follows the closing quote
            if i < n and line[i] == ',':
                i += 1
            elif i < n:
                # Anything else after closing quote is an error
                raise ValueError("invalid character after closing quote")

            fields.append(''.join(field_chars))
        else:
            # Unquoted field
            start = i
            while i < n and line[i] != ',':
                i += 1
            fields.append(line[start:i])
            if i < n and line[i] == ',':
                i += 1

    return fields
