def rle_encode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    if any(c in '0123456789' for c in s):
        raise ValueError("Input must not contain digit characters")
    if not s:
        return ""

    result = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            result.append(f"{count}{s[i - 1]}")
            count = 1
    result.append(f"{count}{s[-1]}")
    return "".join(result)

def rle_decode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    if not s:
        return ""

    i = 0
    result = []
    while i < len(s):
        if not s[i].isdigit():
            raise ValueError("Missing count before character")

        j = i
        while j < len(s) and s[j].isdigit():
            j += 1

        count_str = s[i:j]
        char = s[j]

        if not char:
            raise ValueError("Trailing digits with no character")

        count = int(count_str)
        if count == 0:
            raise ValueError("Count must be at least 1")

        result.append(char * count)
        i = j + 1

    return "".join(result)
