class Emitter {
  constructor() {
    this._events = new Map();
  }

  _ensureEvent(event) {
    if (!this._events.has(event)) {
      this._events.set(event, []);
    }
    return this._events.get(event);
  }

  on(event, fn) {
    if (typeof fn !== 'function') {
      throw new TypeError('fn must be a function');
    }
    const listeners = this._ensureEvent(event);
    listeners.push({ fn, once: false });
    return this;
  }

  once(event, fn) {
    if (typeof fn !== 'function') {
      throw new TypeError('fn must be a function');
    }
    const listeners = this._ensureEvent(event);
    listeners.push({ fn, once: true });
    return this;
  }

  off(event, fn) {
    if (event === undefined) {
      this._events.clear();
      return this;
    }

    let listeners = this._events.get(event);
    if (!listeners) return this;

    // Filter out the specific function
    listeners = listeners.filter(listener => listener.fn !== fn);
    if (listeners.length === 0) {
      this._events.delete(event);
    } else {
      this._events.set(event, listeners);
    }
    return this;
  }

  emit(event, ...args) {
    const listeners = this._events.get(event);
    if (!listeners) return false;

    // Snapshot the list to ensure consistency during emit
    const snapshot = listeners.map(l => l.fn);
    let calledAtLeastOne = false;

    for (const fn of snapshot) {
      calledAtLeastOne = true;
      fn.apply(this, args);
    }

    // Remove 'once' listeners after they are called
    if (listeners) {
      const toRemove = listeners.filter(l => l.once);
      if (toRemove.length > 0) {
        const remaining = listeners.filter(l => !l.once);
        if (remaining.length === 0) {
          this._events.delete(event);
        } else {
          this._events.set(event, remaining);
        }
      }
    }

    return calledAtLeastOne;
  }

  listenerCount(event) {
    const listeners = this._events.get(event);
    return listeners ? listeners.length : 0;
  }
}

