        throw new SyntaxError('Missing end or start in range');
      }

      if (!/^[0-9]+$/.test(loStr) || !/^[0-9]+$/.test(hiStr)) {
        throw new SyntaxError('Invalid characters in range');
      }

      const lo = parseInt(loStr, 10);
