def rle_encode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    if any(c.isdigit() for c in s):
        raise ValueError("Input must not contain digit characters")
    if not s:
        return ""
    result = []
    current_char = s[0]
    count = 1
    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            result.append(f"{count}{current_char}")
            current_char = char
            count = 1
    result.append(f"{count}{current_char}")
    return "".join(result)

def rle_decode(s):
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    if not s:
        return ""
    result = []
    i = 0
    while i < len(s):
        if not s[i].isdigit():
            raise ValueError("Missing count or invalid character sequence")
        count_str = ""
        while i < len(s) and s[i].isdigit():
            count_str += s[i]
            i += 1
        if not count_str:
            raise ValueError("Missing count")
        count = int(count_str)
        if count == 0:
            raise ValueError("Count must be at least 1")
        if i >= len(s):
            raise ValueError("Trailing digits with no character")
        char = s[i]
        if char.isdigit():
            raise ValueError("Character after count must not be a digit")
        result.append(char * count)
        i += 1
    return "".join(result)
