    let calledAtLeastOne = false;
    for (const listener of listeners) {
      listener.apply(this, args);
      calledAtLeastOne = true;
    }
    return calledAtLeastOne;
  }

  listenerCount(event) {
    return this._events.has(event) ? this._events.get(event).length : 0;
