def parse_csv_line(line):
    if not isinstance(line, str):
        raise TypeError("line must be a string")

    fields = []
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            # Start of quoted field
            value = []
            i += 1
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Escaped quote
                        value.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        break
                else:
                    value.append(line[i])
                    i += 1
            else:
                # Loop completed without break -> unclosed quote
                raise ValueError("unterminated quoted field")

            # After closing quote, check for comma or end of line
            if i == n:
                fields.append("".join(value))
                break
            elif line[i] == ',':
                i += 1
            else:
                raise ValueError("invalid characters after closing quote")

            fields.append("".join(value))
        else:
            # Unquoted field
            start = i
            while i < n and line[i] != ',':
                i += 1
            fields.append(line[start:i])

            if i == n:
                break
            elif line[i] == ',':
                i += 1
            else:
                # Should not happen given loop condition, but safety check
                i += 1

    return fields
