            raise ValueError("Version string must not start with 'v'")

        pattern = r'^(\d+)\.(\d+)\.(\d+)(?:-([a-zA-Z0-9-]+))?(?:\+[a-zA-Z0-9-]+)?$'
        match = re.match(pattern, s)
        if not match:
            raise ValueError(f"Invalid version string: {s}")

        major = int(match.group(1))
        minor = int(match.group(2))
        patch = int(match.group(3))

        prerelease_str = match.group(4)
        build_str = match.group(5)

        if prerelease_str:
            if not prerelease_str:
                raise ValueError("Empty prerelease identifier after '-'")
            identifiers = prerelease_str.split('.')
            for ident in identifiers:
                if ident == '':
                    raise ValueError("Empty identifier in prerelease")
                if not re.match(r'^[0-9A-Za-z-]+$', ident):
                    raise ValueError(f"Invalid character in prerelease identifier: {ident}")
                if ident.isdigit() and (len(ident) > 1 and ident[0] == '0'):
                    raise ValueError(f"Leading zeros in numeric prerelease identifier: {ident}")

        return {
            'major': major,
            'minor': minor,
            'patch': patch,
            'prerelease': identifiers if (prerelease_str and (identifiers := prerelease_str.split('.'))) else None,
            'build': build_str
        }

    v1 = parse_version(a)
    v2 = parse_version(b)

    # Compare MAJOR, MINOR, PATCH
    if v1['major'] != v2['major']:
        return -1 if v1['major'] < v2['major'] else 1
    if v1['minor'] != v2['minor']:
        return -1 if v1['minor'] < v2['minor'] else 1
    if v1['patch'] != v2['patch']:
        return -1 if v1['patch'] < v2['patch'] else 1

    # Precedence with prerelease
    # A version with a prerelease has lower precedence than one without
    if v1['prerelease'] and not v2['prerelease']:
        return -1
    if not v1['prerelease'] and v2['prerelease']:
        return 1

    # Both have prerelease or both don't (build is ignored)
    if v1['prerelease'] and v2['prerelease']:
        ids1 = v1['prerelease']
        ids2 = v2['prerelease']

        for i in range(max(len(ids1), len(ids2))):
            p1 = ids1[i] if i < len(ids1) else None
            p2 = ids2[i] if i < len(ids2) else None

            if p1 is None and p2 is not None:
                return 1  # v1 has fewer prerelease identifiers
            if p2 is None and p1 is not None:
                return -1  # v2 has fewer prerelease identifiers

            # Determine if identifiers are numeric
            is_num1 = p1.isdigit()
            is_num2 = p2.isdigit()

            if is_num1 and is_num2:
                # Compare numerically
                num1 = int(p1)
                num2 = int(p2)
                if num1 != num2:
                    return -1 if num1 < num2 else 1
            elif is_num1 and not is_num2:
                # Numeric has lower precedence than alphanumeric
                return -1
            elif not is_num1 and is_num2:
                return 1
            else:
                # Both are alphanumeric (not all digits), compare lexicographically
                if p1 != p2:
                    return -1 if p1 < p2 else 1

        # All shared identifiers are equal, version with more identifiers has higher precedence
        if len(ids1) != len(ids2):
            return 1 if len(ids1) > len(ids2) else -1

    return 0
