    if not isinstance(s, str):
        raise TypeError("input must be str")
    if any(c.isdigit() for c in s):
        raise ValueError("input must not contain digit characters")

    if not s:
        return ""

    result = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            result.append(str(count) + s[i - 1])
            count = 1
    result.append(str(count) + s[-1])
    return "".join(result)


def rle_decode(s):
    if not isinstance(s, str):
        raise TypeError("input must be str")

    if not s:
        return ""

    i = 0
    result = []

    while i < len(s):
        # Parse count
        j = i
        while j < len(s) and s[j].isdigit():
            j += 1

        if i == j:
            raise ValueError("missing count")

        count_str = s[i:j]
        count = int(count_str)

        if count == 0:
            raise ValueError("count cannot be zero")

        # Parse character
        if j >= len(s):
            raise ValueError("trailing digits with no character")

        char = s[j]
        if char.isdigit():
            raise ValueError("character cannot be a digit")

        result.append(char * count)
        i = j + 1

    return "".join(result)
