  }

  const daysInMonth = (m, y) => {
    if (m === 2) {
      return (y % 4 === 0 && (y % 100 !== 0 || y % 400 === 0)) ? 29 : 28;
    }
    if ([4, 6, 9, 11].includes(m)) return 30;
    return 31;
  };

  if (day > daysInMonth(month, year)) {
    throw new RangeError('Invalid calendar date');
  }

  const date = new Date(Date.UTC(year, month - 1, day));
  date.setUTCDate(date.getUTCDate() + days);

  let resultYear = date.getUTCFullYear();
  let resultMonth = date.getUTCMonth() + 1;
  let resultDay = date.getUTCDate();

  if (resultYear < 1 || resultYear > 9999) {
    throw new RangeError('Result year must be between 0001 and 9999');
  }

  const months = [
    '01', '02', '03', '04', '05', '06',
    '07', '08', '09', '10', '11', '12'
  ];
  const dayStr = resultDay.toString().padStart(2, '0');
  const monthStr = months[resultMonth - 1];

