import re

def to_24h(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    text = text.strip()
    if not text:
        raise ValueError("empty text")

    if text.count(':') != 1:
        raise ValueError("missing colon")

    parts = text.split(':')
    if len(parts) != 2:
        raise ValueError("invalid format")

    h_str, m_str = parts

    if not h_str or not m_str:
        raise ValueError("invalid format")

    h_match = re.match(r'^([0-9]+)$', h_str)
    if not h_match:
        raise ValueError("invalid hour format")
    h = int(h_match.group(1))

    if h < 1 or h > 12:
        raise ValueError("hour must be 1 to 12")

    if len(m_str) != 2:
        raise ValueError("minutes must be exactly two digits")

    m_match = re.match(r'^([0-9]+)$', m_str)
    if not m_match:
        raise ValueError("invalid minute format")
    m = int(m_match.group(1))

    if m < 0 or m > 59:
        raise ValueError("minutes must be 00 to 59")

    suffix = m_str[2:] if len(m_str) > 2 else ""

    if suffix:
        suffix = suffix.strip().upper()
        if suffix not in ("AM", "PM"):
            raise ValueError("unknown suffix")
    else:
        raise ValueError("missing AM/PM")

    if h == 12:
        if suffix == "AM":
            h = 0
        # else h remains 12 for PM
    elif suffix == "PM":
        h += 12

    return f"{h:02d}:{m:02d}"
