function formatTable(rows) {
  if (!Array.isArray(rows)) {
    throw new TypeError('rows must be an array');
  }

  if (rows.length > 0) {
    for (const row of rows) {
      if (!Array.isArray(row)) {
        throw new TypeError('each row must be an array');
      }
    }
  }

  const cellWidths = rows.map((row, i) => {
    const width = Math.max(
      0,
      ...row.map((cell, j) => {
        const value = cell === null || cell === undefined ? '' : String(cell);
        return value.length;
      }),
      row.length === 0 ? 0 : 0
    );
    return width;
  });

  const maxColCount = Math.max(...rows.map(r => r.length), 0);
  const result = [];

  for (const row of rows) {
    const paddedRow = new Array(maxColCount).fill('');
    for (let j = 0; j < row.length; j++) {
      const value = row[j] === null || row[j] === undefined ? '' : String(row[j]);
      paddedRow[j] = value;
    }

    const line = paddedRow.map((cell, j) => {
      const width = cellWidths[j];
      return cell.padEnd(width, ' ');
    }).join(' | ');

    result.push(line.trimEnd());
  }

  return result.length === 0 ? '' : result.join('\n');
}

