function addDays(dateStr, days) {
  if (typeof dateStr !== 'string') {
    throw new TypeError('dateStr must be a string');
  }
  if (!Number.isInteger(days)) {
    throw new TypeError('days must be an integer');
  }

  const regex = /^(\d{4})-(\d{2})-(\d{2})$/;
  const match = dateStr.match(regex);
  if (!match) {
    throw new RangeError('dateStr must be exactly YYYY-MM-DD');
  }

  const [, yearStr, monthStr, dayStr] = match;
  const year = parseInt(yearStr, 10);
  const month = parseInt(monthStr, 10);
  const day = parseInt(dayStr, 10);

  if (year < 1 || year > 9999) {
    throw new RangeError('Year must be between 0001 and 9999');
  }

  if (month < 1 || month > 12) {
    throw new RangeError('Month must be between 01 and 12');
  }

  const daysInMonth = new Date(Date.UTC(year, month, 0)).getUTCDate();
  if (day < 1 || day > daysInMonth) {
    throw new RangeError('Invalid date');
  }

  const date = new Date(Date.UTC(year, month - 1, day, 0, 0, 0, 0));
  date.setUTCDate(date.getUTCDate() + days);

  const resultYear = date.getUTCFullYear();
  if (resultYear < 1 || resultYear > 9999) {
    throw new RangeError('Result year is outside 0001..9999');
  }

  const resultMonth = String(date.getUTCMonth() + 1).padStart(2, '0');
  const resultDay = String(date.getUTCDate()).padStart(2, '0');

  const resultYearStr = String(resultYear).padStart(4, '0');

  return `${resultYearStr}-${resultMonth}-${resultDay}`;
}

