    if (cache.has(key)) {
      return cache.get(key);
    }

    try {
      const result = fn.apply(this, args);
      cache.set(key, result);
      return result;
    } catch (e) {
      throw e;
    }
  }

  cached.clear = function () {
    cache.clear();
  };

  return cached;
}

