function formatTable(rows) {
  if (!Array.isArray(rows)) {
    throw new TypeError("rows must be an array");
  }

  const cellToText = (cell) => {
    if (cell === null || cell === undefined) return "";
    return String(cell);
  };

  const textRows = rows.map((row) => {
    if (!Array.isArray(row)) {
      throw new TypeError("each row must be an array");
    }
    return row.map(cellToText);
  });

  const colWidths = textRows.reduce(
    (acc, row) => {
      row.forEach((cell, i) => {
        if (i >= acc.length) {
          acc[i] = cell.length;
        } else {
          acc[i] = Math.max(acc[i], cell.length);
        }
      });
      return acc;
    },
    []
  );

  const maxCols = Math.max(0, colWidths.length);

  return textRows
    .map((row) => {
      const cells = [...row, ...Array.from({ length: maxCols - row.length }, () => "")];
      return cells
        .map((cell, i) => {
          const width = colWidths[i];
          return cell.padEnd(width);
        })
        .join(" | ")
        .trimEnd();
    })
    .join("\n");
}

