def is_balanced(code):
    stack = []
    i = 0
    n = len(code)
    while i < n:
        char = code[i]
        if char == '"':
            # Find the closing quote, handling escapes
            i += 1
            while i < n:
                if code[i] == '\\' and i + 1 < n:
                    i += 2  # Skip escaped character
                elif code[i] == '"':
                    i += 1
                    break
                else:
                    i += 1
            # If we reached the end without finding the closing quote, it's unbalanced
            if i >= n:
                return False
        elif char == '(':
            stack.append(')')
        elif char == '[':
            stack.append(']')
        elif char == '{':
            stack.append('}')
        elif char in (')', ']', '}'):
            if not stack or stack.pop() != char:
                return False
        i += 1
    return not stack

