      const result = fn(attemptNumber);
      return Promise.resolve(result);
    } catch (error) {
      return Promise.reject(error);
    }
  };

  return runAttempt(1).then(
    () => {
      throw new Error('Should not reach here');
    },
    (error) => {
      if (attemptNumber < attempts) {
        return runAttempt(attemptNumber + 1).catch((lastError) => lastError);
      }
      throw error;
    }
  );
