function longestCommonPrefix(strs) {
  if (!Array.isArray(strs)) {
    throw new TypeError('Argument must be an array');
  }

  for (let i = 0; i < strs.length; i++) {
    if (typeof strs[i] !== 'string') {
      throw new TypeError('All elements must be strings');
    }
  }

  if (strs.length === 0) return '';
  if (strs.length === 1) return strs[0];

  const minLen = strs.reduce((min, s) => Math.min(min, s.length), Infinity);
  if (minLen === 0) return '';

  const first = strs[0];
  let prefix = '';

  for (let i = 0; i < minLen; i++) {
    const char = first.charCodeAt(i);

    // Check for high surrogate
    if ((char & 0xFC00) === 0xD800) {
      // This is a high surrogate; must consume the next code unit
      const nextChar = first.charCodeAt(i + 1);
      if ((nextChar & 0xFC00) === 0xDC00) {
        // Valid surrogate pair starting here; include both in prefix
        prefix += first.slice(i, i + 2);
        i += 1; // Loop will increment i again, effectively skipping the low surrogate
      } else {
        // Orphan high surrogate; stop here
        break;
      }
      continue;
    }

    // Check for low surrogate (should not happen in valid string, but safety)
    if ((char & 0xFC00) === 0xDC00) {
      break;
    }

    // Check if all strings have the same character at this position
    let match = true;
    for (let j = 1; j < strs.length; j++) {
      if (i >= strs[j].length) {
        match = false;
        break;
      }
      const otherChar = strs[j].charCodeAt(i);
      if (char !== otherChar) {
        match = false;
        break;
      }
    }

    if (match) {
      prefix += first[i];
    } else {
      break;
    }
  }

  return prefix;
}

