                raise ValueError("Invalid character in grid")

    start = None
    end = None
    rows = len(grid)
    cols = num_cols

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
            elif grid[r][c] == 'E':
                end = (r, c)

    if start is None or end is None:
        raise ValueError("Exactly one start and exactly one end must be present")

    if start == end:
        return 0

    queue = [start]
    visited = {start: 0}
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    while queue:
        r, c = queue.pop(0)
        current_dist = visited[(r, c)]

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            if 0 <= nr < rows and 0 <= nc < cols:
                cell = grid[nr][nc]
                if cell in '.SE' and (nr, nc) not in visited:
                    if (nr, nc) == end:
                        return current_dist + 1
                    visited[(nr, nc)] = current_dist + 1
                    queue.append((nr, nc))

    return -1
