  const b = validateDate(birth);
  const o = validateDate(on);
  if (o < b) throw new RangeError('on must not be earlier than birth');

  let age = o.getFullYear() - b.getFullYear();
  const bMonth = b.getMonth();
  const bDay = b.getDate();
  const oMonth = o.getMonth();
  const oDay = o.getDate();

  if (oMonth < bMonth || (oMonth === bMonth && oDay < bDay)) {
    age--;
  }
  return age;
}

