function retry(fn, attempts) {
  if (!Number.isInteger(attempts) || attempts < 1) {
    return Promise.reject(new RangeError('attempts must be an integer of at least 1'));
  }
  if (typeof fn !== 'function') {
    return Promise.reject(new TypeError('fn must be a function'));
  }

  let attemptNumber = 0;
  let lastError;

  function executeAttempt() {
    if (attemptNumber >= attempts) {
      return Promise.reject(lastError);
    }

    attemptNumber++;
    try {
      const result = fn(attemptNumber);
      const promise = Promise.resolve(result);
      return promise
        .then((value) => {
          // Success: resolve immediately without further attempts
          return value;
        })
        .catch((error) => {
          // Failure: store error and retry if attempts remain
          lastError = error;
          return executeAttempt();
        });
    } catch (error) {
      // Synchronous error: store error and retry if attempts remain
      lastError = error;
      return executeAttempt();
    }
  }

  return executeAttempt();
}

module.exports = { retry };
