        return []

    # Validate input and check for start > end
    for start, end in intervals:
        if start > end:
            raise ValueError("Interval start must not exceed end")

    # Sort intervals by start time
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    merged = [sorted_intervals[0]]

    for current_start, current_end in sorted_intervals[1:]:
        last_start, last_end = merged[-1]

        # If intervals overlap or touch (end of last >= start of current)
        if last_end >= current_start:
            # Merge them by updating the end of the last interval
            merged[-1][1] = max(last_end, current_end)
        else:
            # No overlap, add the current interval to the list
            merged.append([current_start, current_end])

    return merged
