  if (minLen === 0) {
    return '';
  }

  const ref = strs[0];
  for (let i = 0; i < minLen; i++) {
    const code = ref.charCodeAt(i);
    if (code >= 0xD800 && code <= 0xDFFF) {
      throw new Error('Input contains lone surrogates (invalid).');
    }
    if (code >= 0xD800 && code <= 0xDBFF) {
      const next = ref.charCodeAt(i + 1);
      if (next < 0xDC00 || next > 0xDFFF) {
        throw new Error('Input contains lone surrogates (invalid).');
      }
      i++;
    }

    for (let j = 1; j < strs.length; j++) {
      const target = strs[j];
      if (i >= target.length) {
        return ref.slice(0, i);
      }
      const tCode = target.charCodeAt(i);
      if (code !== tCode) {
        return ref.slice(0, i);
