      if (code >= 0xD800 && code <= 0xDBFF) {
        const nextT = target.charCodeAt(i + 1);
        if (next !== nextT) {
          return ref.slice(0, i);
        }
        i++;
      }
    }
  }

  return ref.slice(0, minLen);
}

