function retry(fn, attempts) {
  if (!Number.isInteger(attempts) || attempts < 1) {
    return Promise.reject(new RangeError('attempts must be an integer of at least 1'));
  }
  if (typeof fn !== 'function') {
    return Promise.reject(new TypeError('fn must be a function'));
  }

  return new Promise((resolve, reject) => {
    let lastError = null;

    const attempt = (count) => {
      if (count > attempts) {
        if (lastError) {
          reject(lastError);
        } else {
          // Should not happen if fn always throws or rejects, but for safety:
          reject(new Error('fn rejected or threw without providing an error'));
        }
        return;
      }

      try {
        const result = fn(count);
        // If result is a promise, handle it asynchronously
        if (result instanceof Promise) {
          result
            .then((value) => resolve(value))
            .catch((err) => {
              lastError = err;
              attempt(count + 1);
            });
        } else {
          // If result is a value, resolve immediately
          resolve(result);
        }
      } catch (err) {
        // If fn throws synchronously, handle it
        lastError = err;
        attempt(count + 1);
      }
    };

    attempt(1);
  });
}

module.exports = { retry };
