function createLimiter({ capacity, refillPerSec, now }) {
  if (
    typeof capacity !== 'number' ||
    !Number.isInteger(capacity) ||
    capacity <= 0
  ) {
    throw new RangeError('capacity must be a positive integer');
  }

  if (
    typeof refillPerSec !== 'number' ||
    !isFinite(refillPerSec) ||
    refillPerSec <= 0
  ) {
