def merge_intervals(intervals):
    if not intervals:
        return []

    # Validate intervals and check for start > end
    for start, end in intervals:
        if start > end:
            raise ValueError("Interval start must not exceed end")

    # Sort intervals by start time
    sorted_intervals = sorted(intervals)

    merged = [sorted_intervals[0]]
    current_start, current_end = merged[0]

    for start, end in sorted_intervals[1:]:
        if current_end >= start:
            # Overlapping or touching intervals, merge them
            current_end = max(current_end, end)
        else:
            # Non-overlapping, add the previous interval and start a new one
            merged.append([start, end])
            current_start, current_end = start, end

    return merged
