  if (y < 0 || y > 9999) throw new RangeError("Invalid year");
  if (m < 1 || m > 12) throw new RangeError("Invalid month");
  if (d < 1) throw new RangeError("Invalid day");

  const daysInMonth = [
    0, 31, isLeapYear(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31
  ];
  if (d > daysInMonth[m]) throw new RangeError("Invalid day for month");

