def merge_intervals(intervals):
    if not intervals:
        return []

    # Validate input and check for invalid intervals
    for start, end in intervals:
        if start > end:
            raise ValueError("start must not exceed end")

    # Sort by start time
    sorted_intervals = sorted(intervals, key=lambda x: x[0])

    merged = [sorted_intervals[0][:]]  # Start with the first interval (copy)

    for current_start, current_end in sorted_intervals[1:]:
        last_start, last_end = merged[-1]

        # If the current interval overlaps or touches the last merged interval
        if current_start <= last_end:
            # Merge them by extending the end time
            merged[-1][1] = max(last_end, current_end)
        else:
            # No overlap, add the current interval as a new one (copy)
            merged.append([current_start, current_end])

    return merged
