def maze_steps(grid):
    if not grid:
        raise ValueError("Grid cannot be empty")

    rows = len(grid)
    cols = len(grid[0])

    # Check row lengths
    for row in grid:
        if len(row) != cols:
            raise ValueError("All rows must be of equal length")

    # Validate characters and count S/E
    start_pos = None
    end_pos = None
    valid_chars = {'S', 'E', '#', '.'}

    for r in range(rows):
        for c in range(cols):
            char = grid[r][c]
            if char not in valid_chars:
                raise ValueError(f"Invalid character: {char}")
            if char == 'S':
                if start_pos is not None:
                    raise ValueError("Multiple start positions found")
                start_pos = (r, c)
            elif char == 'E':
                if end_pos is not None:
                    raise ValueError("Multiple end positions found")
                end_pos = (r, c)

    if start_pos is None or end_pos is None:
        raise ValueError("Exactly one start and one end position required")

    # BFS initialization
    queue = deque([(start_pos[0], start_pos[1], 0)])
    visited = set([start_pos])

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    while queue:
        r, c, steps = queue.popleft()

        if (r, c) == end_pos:
            return steps

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited:
                if grid[nr][nc] != '#':
                    visited.add((nr, nc))
                    queue.append((nr, nc, steps + 1))

    return -1
