                    raise ValueError("Multiple start positions found")
                start = (r, c)
            elif grid[r][c] == 'E':
                if end is not None:
                    raise ValueError("Multiple end positions found")
                end = (r, c)

    if start is None or end is None:
        raise ValueError("Missing start or end position")

    queue = [start]
    visited = {start}
    steps = {start: 0}

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    while queue:
        r, c = queue.pop(0)
        current_steps = steps[(r, c)]

        if (r, c) == end:
