def validate_username(name):
    if not isinstance(name, str):
        raise TypeError("name must be a string")

    normalized = name.strip().lower()

    if len(normalized) < 3 or len(normalized) > 20:
        raise ValueError("username length must be between 3 and 20 characters")

    if not normalized[0].isalpha() or not normalized[0].isascii():
        raise ValueError("username must start with an ASCII letter")

    if normalized[-1] in ('_', '.'):
        raise ValueError("username must not end with '_' or '.'")

    special_chars = set('_')
    special_chars.add('.')

    for char in normalized:
        if not (char.isalnum() or char in special_chars):
            raise ValueError("username can only contain ASCII letters, digits, '_', and '.'")

    for i in range(len(normalized) - 1):
        if normalized[i] in special_chars and normalized[i + 1] in special_chars:
            raise ValueError("username cannot have two special characters next to each other")

    return normalized
