def maze_steps(grid):
    if not grid:
        raise ValueError("Grid cannot be empty")

    rows = len(grid)
    cols = len(grid[0])

    for row in grid:
        if len(row) != cols:
            raise ValueError("All rows must have the same length")
        for char in row:
            if char not in 'SE#.':
                raise ValueError(f"Invalid character: {char}")

    start = None
    end = None

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                if start is not None:
                    raise ValueError("Multiple start points found")
                start = (r, c)
            elif grid[r][c] == 'E':
                if end is not None:
                    raise ValueError("Multiple end points found")
                end = (r, c)

    if start is None or end is None:
        raise ValueError("Exactly one 'S' and one 'E' must be present")

    queue = [(start[0], start[1], 0)]
    visited = set([start])

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    while queue:
        r, c, dist = queue.pop(0)

        if (r, c) == end:
            return dist

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited and grid[nr][nc] != '#':
                visited.add((nr, nc))
                queue.append((nr, nc, dist + 1))

    return -1
